/** Value comparison for selected view snapshots. Identity is the fast path. Callers must
 * replace changed objects: mutating a published snapshot in place is unsupported. */
export function sameSelection(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true
  if (!a || !b || typeof a !== 'object' || typeof b !== 'object') return false
  if (Array.isArray(a) !== Array.isArray(b)) return false
  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false
  if (!Array.isArray(a) && Object.getPrototypeOf(a) !== Object.prototype) return false
  const left = a as Record<string, unknown>, right = b as Record<string, unknown>
  const keys = Object.keys(left)
  return keys.length === Object.keys(right).length && keys.every(key => Object.hasOwn(right, key) && sameSelection(left[key], right[key]))
}

/** Keyed delivery with selected-value equality. Reentrant notifications are drained after
 * the current pass; unsubscribing during delivery prevents a stale callback. */
export class SelectionHub {
  private entries = new Map<string, Set<{ read: () => unknown, value: unknown, notify: () => void, active: boolean }>>()
  private pending = new Set<string>()
  private delivering = false

  subscribe(key: string | readonly string[], read: () => unknown, notify: () => void): () => void {
    const keys = typeof key === 'string' ? [key] : [...new Set(key)]
    const entry = { read, value: read(), notify, active: true }
    for (const key of keys) {
      let entries = this.entries.get(key)
      if (!entries) this.entries.set(key, entries = new Set())
      entries.add(entry)
    }
    return () => {
      entry.active = false
      for (const key of keys) {
        const entries = this.entries.get(key)
        entries?.delete(entry)
        if (!entries?.size) this.entries.delete(key)
      }
    }
  }

  notify(keys: Iterable<string> = this.entries.keys()): void {
    for (const key of keys) this.pending.add(key)
    if (this.delivering) return
    this.delivering = true
    try {
      while (this.pending.size) {
        const keys = [...this.pending]
        this.pending.clear()
        const entries = new Set(keys.flatMap(key => [...this.entries.get(key) ?? []]))
        for (const entry of entries) {
          if (!entry.active) continue
          const next = entry.read()
          if (sameSelection(entry.value, next)) continue
          entry.value = next
          entry.notify()
        }
      }
    } finally { this.delivering = false }
  }
}
